import{_ as e,o as s,c as i,a6 as o}from"./chunks/framework.DL_pga9_.js";const h=JSON.parse('{"title":"Symbol Import Aliases","description":"","frontmatter":{},"headers":[],"relativePath":"design/symbol_import_aliases.md","filePath":"design/symbol_import_aliases.md","lastUpdated":1780030916000}'),t={name:"design/symbol_import_aliases.md"};function n(l,a,r,c,d,p){return s(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="symbol-import-aliases" tabindex="-1">Symbol Import Aliases <a class="header-anchor" href="#symbol-import-aliases" aria-label="Permalink to “Symbol Import Aliases”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Future design. This is intentionally separated from current module artifact, stdlib modularization, and bytecode loading work. Current implemented conflict avoidance is module-qualified access:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import first.module as first;</span></span>
<span class="line"><span>import second.module as second;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>first.name();</span></span>
<span class="line"><span>second.name();</span></span></code></pre></div><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Allow callers to keep short local names when two modules export symbols with the same public name, without weakening import provenance or trait/impl coherence.</p><h2 id="proposed-syntax" tabindex="-1">Proposed Syntax <a class="header-anchor" href="#proposed-syntax" aria-label="Permalink to “Proposed Syntax”">​</a></h2><div class="language-ebnf"><button title="Copy Code" class="copy"></button><span class="lang">ebnf</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ImportDecl := ExportPrefix? &quot;import&quot; ModulePath ImportAlias? ImportList? &quot;;&quot;</span></span>
<span class="line"><span>ExportPrefix := &quot;export&quot;</span></span>
<span class="line"><span>ImportAlias := &quot;as&quot; Ident</span></span>
<span class="line"><span>ImportList := &quot;(&quot; (&quot;*&quot; | ImportItem (&quot;,&quot; ImportItem)*) &quot;)&quot;</span></span>
<span class="line"><span>ImportItem := Ident (&quot;as&quot; Ident)?</span></span></code></pre></div><p>Examples:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import first.module (name as firstName);</span></span>
<span class="line"><span>import second.module (name as secondName);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export import std.string (join as stringJoin);</span></span></code></pre></div><h2 id="semantics" tabindex="-1">Semantics <a class="header-anchor" href="#semantics" aria-label="Permalink to “Semantics”">​</a></h2><ul><li><code>import m (aaa as bbb);</code> binds local name <code>bbb</code> to exported symbol <code>aaa</code>.</li><li>Provenance records the canonical source module ID and original exported name separately from the local alias.</li><li>Conflict checks are local-name based. <code>aaa as bbb</code> conflicts with any other imported or local symbol named <code>bbb</code> from a different source.</li><li>Re-importing the same original symbol from the same canonical source under the same local alias is idempotent.</li><li>Diagnostics must report the local alias, original symbol, and canonical source module.</li><li><code>export import m (aaa as bbb);</code> exports <code>bbb</code> as this module&#39;s public symbol, while preserving provenance to <code>m::aaa</code>.</li><li>Module-qualified imports remain available and are preferred when many symbols from both modules are needed.</li><li><code>use impl Trait for Type</code> continues to use module qualifiers and canonical module IDs. Symbol aliases do not create new trait or type identities.</li></ul><h2 id="required-data" tabindex="-1">Required Data <a class="header-anchor" href="#required-data" aria-label="Permalink to “Required Data”">​</a></h2><ul><li>AST import item structure with <code>exportedName</code> and optional <code>localName</code>.</li><li>Runtime/module artifact import provenance entries containing: local name, original exported name, canonical source module ID.</li><li>Typechecker import metadata that distinguishes local alias from original export name for diagnostics and re-export artifact publication.</li><li>ORGASM import metadata that can emit <code>CALL_IMPORT</code> by original exported name while binding the local alias during compilation.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li>Parser accepts <code>import m (aaa as bbb);</code> and rejects malformed alias items.</li><li>STUPID and ORGASM both execute calls through aliased imported functions.</li><li>Imported values, functions, types, traits, and impl evidence preserve original module provenance through aliases.</li><li>Conflicts are detected by local name and include both source modules in the diagnostic.</li><li><code>export import m (aaa as bbb);</code> re-exports <code>bbb</code> and downstream imports can use <code>bbb</code> without knowing the original <code>aaa</code> name.</li><li><code>.ngo</code> artifacts preserve alias metadata so source and bytecode modules expose the same public symbols.</li></ul>`,16)])])}const u=e(t,[["render",n]]);export{h as __pageData,u as default};
